+/// Rimuove un processo da una lista di attesa
+static void rimuovi_da_lista(des_proc*& p_lista, des_proc* p_elem)
+{
+	if (p_lista == p_elem) {
+		p_lista = p_elem->puntatore;
+		p_elem->puntatore = nullptr;
+		return;
+	}
+	
+	des_proc* prev = nullptr;
+	des_proc* curr = p_lista;
+	while (curr && curr != p_elem) {
+		prev = curr;
+		curr = curr->puntatore;
+	}
+	
+	if (curr) {
+		prev->puntatore = curr->puntatore;
+		curr->puntatore = nullptr;
+	}
+}
+
+/// Parte C++ della primitiva rw_upgrade()
+extern "C" void c_rw_upgrade(natl rw)
+{
+	if (!rw_valido(rw)) {
+		flog(LOG_WARN, "rw_upgrade(%d): rwlock non valido", rw);
+		c_abort_p();
+		return;
+	}
+
+	des_rw *r = &array_desrw[rw];
+	des_proc_rw *rp = rw_proc_find(r);
+
+	if (!rp) {
+		flog(LOG_WARN, "rw_upgrade(%d): processo non ha lock su rw", rw);
+		c_abort_p();
+		return;
+	}
+
+	if (rp->state != RW_READER) {
+		flog(LOG_WARN, "rw_upgrade(%d): processo non ha read lock", rw);
+		c_abort_p();
+		return;
+	}
+
+	r->nreaders--;
+	
+	if (r->nreaders == 0 && !r->writer) {
+		rp->state = RW_UPGRADED;
+		r->writer = esecuzione->id;
+	} else {
+		rp->state = RW_NONE;
+		inserimento_lista(r->w_writers, esecuzione);
+		schedulatore();
+	}
+}
+
+/// Parte C++ della primitiva rw_downgrade()
+extern "C" void c_rw_downgrade(natl rw)
+{
+	if (!rw_valido(rw)) {
+		flog(LOG_WARN, "rw_downgrade(%d): rwlock non valido", rw);
+		c_abort_p();
+		return;
+	}
+
+	des_rw *r = &array_desrw[rw];
+	des_proc_rw *rp = rw_proc_find(r);
+
+	if (!rp) {
+		flog(LOG_WARN, "rw_downgrade(%d): processo non ha lock su rw", rw);
+		c_abort_p();
+		return;
+	}
+
+	if (rp->state == RW_UPGRADED) {
+		rp->state = RW_READER;
+		r->nreaders++;
+		r->writer = 0;
+	} else if (rp->state == RW_READER) {
+		r->nreaders--;
+		rp->r = nullptr;
+		rp->state = RW_NONE;
+	} else if (rp->state == RW_WRITER) {
+		r->writer = 0;
+		rp->r = nullptr;
+		rp->state = RW_NONE;
+	}
+
+	if (r->w_readers) {
+		des_proc* lavoro = rimozione_lista(r->w_readers);
+		rimuovi_da_lista(r->w_writers, lavoro);
+		des_proc_rw* lrp = rw_proc_find(r, lavoro);
+		inserimento_lista(pronti, lavoro);
+		lrp->state = RW_READER;
+		r->nreaders++;
+		schedulatore();
+	} else if (r->w_writers) {
+		des_proc* lavoro = rimozione_lista(r->w_writers);
+		des_proc_rw* lrp = rw_proc_find(r, lavoro);
+		inserimento_lista(pronti, lavoro);
+		lrp->state = RW_WRITER;
+		r->writer = lavoro->id;
+		schedulatore();
+	}
+}
 //   ESAME 2024-09-11 )

 /// @}
